/**
 * CORRECAO - fotos abrindo todas de uma vez + download no Safari do iPhone
 *
 * 1) FOTOS ABRINDO TODAS
 *
 * A logica que decide quais grupos de data ficam abertos tinha um defeito:
 * ela so sabia lidar com "nenhum grupo foi tocado ainda" (so o mais recente
 * abre) ou "pelo menos um foi tocado" (nesse caso, esquecia o mais recente
 * e passava a depender so de uma lista). Bastava tocar em qualquer grupo
 * para o comportamento ficar imprevisivel - inclusive parecendo que tudo
 * abria de uma vez, dependendo da ordem dos cliques.
 *
 * Agora cada grupo guarda seu proprio estado (aberto ou fechado)
 * independente dos outros. Ao abrir a aba, so a visita mais recente vem
 * aberta; as demais ficam fechadas ate voce clicar para expandir - e
 * clicar numa nao afeta as outras.
 *
 * 2) DOWNLOAD DE FOTO NO IPHONE
 *
 * O Safari do iPhone ignora o pedido de download em links comuns e abre
 * uma tela intermediaria ("Abrir com Instagram", "Mais..."), exigindo um
 * segundo toque para salvar de verdade.
 *
 * Este arquivo ja tinha a correcao certa escrita (buscar o arquivo antes e
 * entregar pronto, o que faz o Safari salvar direto), mas ela pode nao ter
 * chegado a ser publicada ainda. Este script garante que ela vai junto.
 *
 * Se depois de publicar o download ainda abrir a tela intermediaria, avise
 * que investigamos mais a fundo - pode ser algo especifico do aparelho.
 *
 * Como usar: coloque este arquivo na RAIZ do projeto e rode
 *     node corrigir-fotos-e-busca.mjs
 *
 * E seguro rodar duas vezes.
 */

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { Buffer } from "node:buffer";

const ARQUIVO = "app/(app)/clientes/components/ClienteClinicoTabs.tsx";

console.log("\nCorrecao - fotos fechadas por padrao + download no iPhone\n");

if (!existsSync(ARQUIVO) || !existsSync("package.json")) {
  console.error("ERRO: rode este script na pasta raiz do projeto (a mesma do package.json).\n");
  process.exit(1);
}

